1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Modules\Events\Enums;
6	
7	/**
8	 * Story 2-1 — Canonical event state machine (Phase 1, 8 states, 20 legal edges).
9	 *
10	 * Single source of truth: docs/specs/event-states.md (PF-1 Reading A,
11	 * reconciled 2026-04-25).
12	 *
13	 * - DB column: VARCHAR — values match the lowercase string values below.
14	 * - SUSPENDED is reachable from any non-SUSPENDED state via EventService::suspend().
15	 * - Reactivation from SUSPENDED uses the audit ledger (see Story 2-6 sketch).
16	 */
17	enum EventState: string
18	{
19	    case DRAFT = 'draft';
20	    case PUBLISHED = 'published';
21	    case PREPARING = 'preparing';
22	    case READY = 'ready';
23	    case LIVE = 'live';
24	    case ENDED = 'ended';
25	    case FAILED = 'failed';
26	    case SUSPENDED = 'suspended';
27	
28	    /**
29	     * Canonical legal-transition table. Mirrors docs/specs/event-states.md.
30	     *
31	     * @return list<self>
32	     */
33	    public function transitionsTo(): array
34	    {
35	        return match ($this) {
36	            self::DRAFT => [self::PUBLISHED, self::SUSPENDED, self::FAILED],
37	            self::PUBLISHED => [self::PREPARING, self::SUSPENDED, self::FAILED],
38	            self::PREPARING => [self::READY, self::FAILED, self::SUSPENDED],
39	            self::READY => [self::LIVE, self::FAILED, self::SUSPENDED],
40	            self::LIVE => [self::ENDED, self::FAILED, self::SUSPENDED, self::READY],
41	            self::ENDED => [self::FAILED, self::SUSPENDED],
42	            self::FAILED => [self::PREPARING, self::SUSPENDED],
43	            self::SUSPENDED => [],
44	        };
45	    }
46	
47	    public function canTransitionTo(self $next): bool
48	    {
49	        return in_array($next, $this->transitionsTo(), strict: true);
50	    }
51	
52	    /** SUSPENDED is reachable from any non-SUSPENDED state. */
53	    public function canBeSuspendedFrom(): bool
54	    {
55	        return $this !== self::SUSPENDED;
56	    }
57	
58	    /** True when the event row's core metadata is read-only. */
59	    public function isMetadataLocked(): bool
60	    {
61	        return $this !== self::DRAFT;
62	    }
63	
64	    /**
65	     * True when the event must reject new registrations.
66	     * DRAFT blocks because the landing page is private until PUBLISHED.
67	     */
68	    public function blocksRegistration(): bool
69	    {
70	        return in_array($this, [self::DRAFT, self::ENDED, self::FAILED, self::SUSPENDED], strict: true);
71	    }
72	
73	    /**
74	     * Story 5-14 — True when the event is in a state that supports live
75	     * streaming operations (control room, go-live, end-event).
76	     *
77	     * Single source of truth for the READY|LIVE check previously duplicated
78	     * across EventActionAvailability, ControlRoomController::isOperable,
79	     * and StreamingLifecycleService claim methods.
80	     */
81	    public function isLiveOperable(): bool
82	    {
83	        return $this === self::READY || $this === self::LIVE;
84	    }
85	
86	    /**
87	     * Story 5-14 — True when the event has reached the terminal ENDED state.
88	     */
89	    public function isEnded(): bool
90	    {
91	        return $this === self::ENDED;
92	    }
93	
94	    /** Translation key for UI label. Resolves through __() at render-time. */
95	    public function label(): string
96	    {
97	        return __('events.state.' . $this->value);
98	    }
99	
100	    /** @return list<string> */
101	    public static function values(): array
102	    {
103	        return array_map(static fn (self $s) => $s->value, self::cases());
104	    }
105	
106	    // ─────────────────────────────────────────────────────────────────
107	    // Story 3-17 — Public visibility helpers
108	    // ─────────────────────────────────────────────────────────────────
109	
110	    /**
111	     * Is the event completely hidden from public visitors?
112	     * DRAFT and FAILED events are never publicly addressable, regardless of
113	     * cancellation state. Cancelled-DRAFT is covered by DRAFT.
114	     */
115	    public function isPubliclyHidden(): bool
116	    {
117	        return in_array($this, [self::DRAFT, self::FAILED], strict: true);
118	    }
119	
120	    /**
121	     * Which public page shell should render?
122	     *
123	     * S3-4-F3 — This is a two-level dispatch: shellFor() selects the public page
124	     * mode (landing/cancelled/suspended), then the Blade second-level dispatch
125	     * selects the viewer sub-shell via registrantViewerMode().
126	     *
127	     * @param bool $cancelled Whether cancelled_at is set on the event row
128	     */
129	    public function publicShell(bool $cancelled): string
130	    {
131	        if ($cancelled) {
132	            return 'cancelled';
133	        }
134	
135	        return match ($this) {
136	            self::SUSPENDED => 'suspended',
137	            default => 'landing',
138	        };
139	    }
140	
141	    /**
142	     * Which viewer sub-shell should render when a registrant is authenticated?
143	     * Returns null for states where registrant viewer access is not applicable.
144	     *
145	     * @return ?string 'registered' | 'live' | 'ended' | null
146	     */
147	    public function registrantViewerMode(): ?string
148	    {
149	        return match ($this) {
150	            self::PUBLISHED,
151	            self::PREPARING,
152	            self::READY => 'registered',
153	            self::LIVE => 'live',
154	            self::ENDED => 'ended',
155	            default => null,
156	        };
157	    }
158	
159	    /**
160	     * Is this event eligible for public indexing (sitemap, registrant access links)?
161	     *
162	     * @param bool $cancelled Whether cancelled_at is set on the event row
163	     */
164	    public function isPubliclyIndexable(bool $cancelled): bool
165	    {
166	        if ($cancelled) {
167	            return false;
168	        }
169	
170	        return in_array($this, [
171	            self::PUBLISHED,
172	            self::PREPARING,
173	            self::READY,
174	            self::LIVE,
175	            self::ENDED,
176	        ], strict: true);
177	    }
178	}
