2	
3	declare(strict_types=1);
4	
5	namespace App\Modules\Events\Services;
6	
7	use App\Models\User;
8	use App\Modules\Events\Contracts\Repositories\EventRepositoryInterface;
9	use App\Modules\Events\Enums\EventState;
10	use App\Modules\Events\Events\EventStateTransitioned;
11	use App\Modules\Events\Exceptions\EventStateLocked;
12	use App\Modules\Events\Exceptions\IllegalStateTransition;
13	use App\Modules\Events\Models\Event;
14	use Illuminate\Support\Facades\DB;
15	use Illuminate\Support\Facades\Event as EventDispatcher;
16	use Platform\AuditLogging\Contracts\AuditLoggerInterface;
17	use App\Modules\Events\Support\EventAuditEvents;
18	
19	/**
20	 * Epic 2 refactor — state-machine hub extracted from EventService.
21	 *
22	 * Move-only: transition() and authorizeEventTransition() are byte-for-byte
23	 * from EventService L1331–L1474. The only edits inside the moved bodies are
24	 * mechanical rewrites of $this->X(...) calls onto explicit collaborator fields.
25	 *
26	 * Extracted first because publish/forceEnd delegate to transition(), making
27	 * this the dependency hub for all lifecycle/moderation clusters.
28	 */
29	class EventStateMachineService
30	{
31	    public function __construct(
32	        private readonly AuditLoggerInterface $auditLogger,
33	        private readonly EventRepositoryInterface $events,
34	        private readonly EventAuthorizationService $authz,
35	    ) {}
36	
37	    /**
38	     * Story 2-3a — central state-transition method.
39	     *
40	     * Concurrency contract (R-002):
41	     *   1. lockForUpdate the event row (events row only — no nested locks).
42	     *   2. Re-read state inside the lock.
43	     *   3. Re-check `cancelled_at IS NULL` — cancellation always wins forward transitions (§10 Q2).
44	     *   4. Same-state? No-op return — supports double-click + scheduler retry idempotency.
45	     *   5. Validate canTransitionTo; if illegal, emit `event.transition_denied` audit then throw.
46	     *   6. Write state + audit row in same tx.
47	     *   7. Dispatch domain event AFTER tx commits (post-commit only).
48	     *
49	     * Race-sim coverage (P0 race pairs) is exercised by
50	     * tests/Feature/Events/EventRaceTest using the EventRaceSimulator fixture.
51	     */
52	    public function transition(
53	        Event $event,
54	        EventState $next,
55	        User $actor,
56	        string $reason = '',
57	        bool $allowForceEndAuthority = false,
58	    ): Event
59	    {
60	        // R1 BLOCKER #1 — service-layer Gate assertion (Rule 30 + Epic 1 canon).
61	        // Provider-context system actors are admitted via events.update.global;
62	        // user-context callers need events.update.team OR a Gate-allowed
63	        // provider grant. Per-target capabilities (one per
64	        // EventState value) are deferred — they'd need 7 cap rows per role and
65	        // add no real safety beyond the wrapper checks (publish/suspend/cancel
66	        // each layer their own gate). Rationale tracked in story Completion Notes.
67	        $this->authorizeEventTransition($event, $next, $actor, $allowForceEndAuthority);
68	
69	        // R2 BLOCKER #2 — separate-tx pattern for denied audit.
70	        // Outer tx ONLY locks + reads + (on legal edge) writes state + audit.
71	        // Denied path returns the 'denied' signal WITHOUT touching the audit;
72	        // the verifier emits the denied audit in its OWN transaction outside
73	        // the closure (so a logger throw rolls back ONLY the audit savepoint
74	        // and never masks the IllegalStateTransition that follows).
75	        // R1 HIGH #4 — drop TeamScope inside the service: the Gate above
76	        // enforces tenancy explicitly, so falling-through to ModelNotFoundException
77	        // (404) when a SystemAdmin acts cross-team would be wrong.
78	        $result = DB::transaction(function () use ($event, $next, $actor, $reason): array {
79	            $fresh = $this->events->lockEventForServiceWrite($event->getKey());
80	
81	            // R1 HIGH #3 — cancellation re-check ABOVE same-state.
82	            // A same-state call on a cancelled event must throw, not silently no-op.
83	            if ($fresh->cancelled_at !== null) {
84	                throw EventStateLocked::for($fresh);
85	            }
86	
87	            if ($fresh->state === $next) {
88	                return [$fresh, $fresh->state, 'noop'];
89	            }
90	
91	            if (! $fresh->state->canTransitionTo($next)) {
92	                // Do NOT log here — the closure-throw + DB::transaction would
93	                // rollback any audit row we wrote AND re-raise the logger's
94	                // RuntimeException, masking IllegalStateTransition. Bubble
95	                // the decision out and let the post-tx block handle it.
96	                return [$fresh, $fresh->state, 'denied'];
97	            }
98	
99	            $from = $fresh->state;
100	            $fresh->state = $next;
101	            $fresh->save();
102	
103	            // Success-path audit MUST stay inside the outer tx (AC1 invariant:
104	            // state mutation + audit emission are atomic; logger throw rolls
105	            // back state). Tested by `domain_event_is_not_dispatched_when_transaction_rolls_back`.
106	            $this->auditLogger->log(
107	                event: EventAuditEvents::EVENT_TRANSITIONED,
108	                description: "Event {$fresh->getKey()} transitioned {$from->value} -> {$next->value}",
109	                subject: $actor,
110	                target: $fresh,
111	                properties: [
112	                    'team_id' => $fresh->team_id,
113	                    'event_uuid' => $fresh->uuid,
114	                    'from' => $from->value,
115	                    'to' => $next->value,
116	                    'reason' => $reason,
117	                ],
118	            );
119	
120	            return [$fresh, $from, 'changed'];
121	        });
122	
123	        [$fresh, $from, $outcome] = $result;
124	
125	        if ($outcome === 'denied') {
126	            // R2 BLOCKER #2 — emit denied audit in a SEPARATE tx so a logger
127	            // throw rolls back ONLY this audit (not any prior writes — outer tx
128	            // already committed cleanly with no writes). Catch any logger
129	            // failure with `report()` and ALWAYS throw IllegalStateTransition,
130	            // so the state-machine outcome is never masked by audit-storage.
131	            try {
132	                DB::transaction(function () use ($fresh, $next, $actor, $reason): void {
133	                    $this->auditLogger->log(
134	                        event: EventAuditEvents::EVENT_TRANSITION_DENIED,
135	                        description: "Event {$fresh->getKey()} transition denied {$fresh->state->value} -> {$next->value}",
136	                        subject: $actor,
137	                        target: $fresh,
138	                        properties: [
139	                            'team_id' => $fresh->team_id,
140	                            'event_uuid' => $fresh->uuid,
141	                            'from' => $fresh->state->value,
142	                            'to_attempted' => $next->value,
143	                            'reason' => $reason,
144	                        ],
145	                    );
146	                });
147	            } catch (\Throwable $auditFailure) {
148	                // Best-effort: log the audit-storage failure but do NOT mask
149	                // the state-machine outcome. The caller still gets the
150	                // semantically-correct exception type.
151	                if (function_exists('report')) {
152	                    report($auditFailure);
153	                } else {
154	                    error_log('[EventStateMachineService] denied-audit storage failure: '.$auditFailure->getMessage());
155	                }
156	            }
157	
158	            throw IllegalStateTransition::between($from, $next);
159	        }
160	
161	        // Post-commit dispatch — never inside the tx (Epic 1 R8-H1 lesson).
162	        // DB::afterCommit() queues until the OUTERMOST tx commits, so a caller
163	        // wrapping transition() in their own DB::transaction() that later rolls
164	        // back does NOT see the dispatch fire. Without this, the inner-tx
165	        // commit triggers immediately even when an outer tx rolls back. Pinned
166	        // by `tests/Feature/Events/Domain/EventDomainEventDispatchOrderTest`.
167	        if ($outcome === 'changed') {
168	            DB::afterCommit(static fn () => EventDispatcher::dispatch(
169	                new EventStateTransitioned($fresh, $from, $next, $actor),
170	            ));
171	        }
172	
173	        return $fresh;
174	    }
175	
176	    /**
177	     * Service-layer transition authorization.
178	     *
179	     * Delegates to EventAuthorizationService — single source of truth. The
180	     * general path requires update authority; the force-end bypass is available
181	     * only when the forceEnd wrapper passes the explicit context flag.
182	     */
183	    public function authorizeEventTransition(
184	        Event $event,
185	        EventState $next,
186	        User $actor,
187	        bool $allowForceEndAuthority = false,
188	    ): void
189	    {
190	        if ($allowForceEndAuthority) {
191	            $this->authz->authorizeForceEndTransition($event, $next, $actor);
192	
193	            return;
194	        }
195	
196	        $this->authz->authorizeTransition($event, $actor);
197	    }
198	}
