30	/**
31	 * Epic 2 refactor — lifecycle cluster extracted from EventService (publish + cancel).
32	 *
33	 * Move-only: all bodies are byte-for-byte from EventService.
34	 * Mechanical rewrites:
35	 *   - $this->transition(...) → $this->stateMachine->transition(...) in publish() (1 site)
36	 *   - $this->authorizeEventPublish(...) → $this->authorizeEventPublish(...) (stays private here)
37	 *   - $this->authorizeEventCancel(...) → $this->authorizeEventCancel(...) (stays private here)
38	 *   - $this->entitlements → $this->entitlements (promoted to constructor param)
39	 * Error-log tag updated: '[EventService]' → '[EventLifecycleService]'.
40	 */
41	class EventLifecycleService
42	{
43	    public const PUBLISH_REASON_PLAN_GATE = 'plan_gate';
