45	    public function __construct(
46	        private readonly AuditLoggerInterface $auditLogger,
47	        private readonly EntitlementChecker $entitlements,
48	        private readonly EventRepositoryInterface $events,
49	        private readonly EventStateMachineService $stateMachine,
50	        private readonly EventAuthorizationService $authz,
51	        private readonly AiAuditRequestService $aiAuditRequests,
52	        private readonly PlatformKillSwitchService $killSwitches,
53	        private readonly EventOperationalLockService $operationalLocks,
