56	    public function publish(Event $event, User $actor): Event
57	    {
58	        // R1 BLOCKER #1 (2-3b) — service-layer Gate.
59	        // events.publish.team is Admin-only (per AC5: Co-host CANNOT publish).
60	        // This MUST run before the entitlement check so a Co-host on a Pro
61	        // plan does not fall through into transition() via events.update.team.
62	        // Entitlement/plan-gate check is NOT here — it stays in publish() after this call.
63	        $this->authz->authorizePublish($event, $actor);
64	
65	        $this->assertMutablePublishPrerequisites($event, $actor);
66	
67	        if ($event->state === EventState::PUBLISHED) {
68	            return $this->stateMachine->transition($event, EventState::PUBLISHED, $actor, 'admin.publish');
69	        }
70	
71	        // Phase 1: the explicit organizer command may create/reuse and
72	        // synchronously triage the current snapshot. Provider I/O happens
73	        // before any event transaction or event-row lock.
74	        $decision = $this->aiAuditRequests->ensureCurrentPublishDecisionOrRequest($event);
75	
76	        if (! $decision->isApproved()) {
77	            throw PublishPrerequisiteMissing::aiAudit($event, $decision->status);
78	        }
79	
80	        // Provider latency creates a new authorization boundary. Reload the
81	        // actor/team context and invalidate its supported permission cache
82	        // before re-running the publish capability guard. Authorization must
83	        // remain outside every transaction and row lock.
84	        $freshActor = User::query()
85	            ->with('currentTeam')
86	            ->findOrFail($actor->getKey());
87	        $freshActor->clearAllPermissionCache();
88	        $this->authz->authorizePublish($event, $freshActor);
89	
90	        // Phase 2: serialize content writers on the event row, reload every
91	        // mutable gate, and recompute the E-AIA-owned current-snapshot result.
92	        // EventStateMachineService remains the sole state writer and owns the
93	        // atomic transition audit plus after-commit domain event.
94	        return DB::transaction(function () use ($event, $freshActor): Event {
95	            $fresh = $this->events->lockEventForServiceWrite($event->getKey());
96	
97	            if ($fresh->state === EventState::PUBLISHED) {
98	                return $fresh;
99	            }
100	
101	            $this->assertMutablePublishPrerequisites($fresh, $freshActor, freshEntitlement: true);
102	
103	            $finalDecision = $this->aiAuditRequests->lockCurrentPublishDecisionForEvent($fresh);
104	
105	            if (! $finalDecision->isApproved()) {
106	                throw PublishPrerequisiteMissing::aiAudit($fresh, $finalDecision->status);
107	            }
108	
109	            return $this->stateMachine->transition($fresh, EventState::PUBLISHED, $freshActor, 'admin.publish');
110	        }, attempts: 1);
111	    }
112	
113	    private function assertMutablePublishPrerequisites(
114	        Event $event,
115	        User $actor,
116	        bool $freshEntitlement = false,
117	    ): void {
118	        if ($this->killSwitches->active(PlatformKillSwitchKey::PUBLISH)) {
119	            throw new PlatformKillSwitchActiveException(PlatformKillSwitchKey::PUBLISH);
120	        }
121	
122	        if ($this->operationalLocks->active($event, EventOperationalLockKey::PUBLISH)) {
123	            throw new EventOperationalLockActive($event, EventOperationalLockKey::PUBLISH);
124	        }
125	
126	        $hasPublishEntitlement = $freshEntitlement
127	            ? $this->entitlements->hasFreshEntitlementForTeam($actor, $event->team_id, 'PUBLISH')
128	            : $this->entitlements->hasEntitlementForTeam($actor, $event->team_id, 'PUBLISH');
129	
130	        if (! $hasPublishEntitlement) {
131	            throw PlanGateFailed::for($event, 'PUBLISH');
132	        }
133	
134	        if ($event->cancelled_at !== null) {
135	            throw EventStateLocked::for($event);
136	        }
137	
138	        if (! in_array($event->state, [EventState::DRAFT, EventState::PUBLISHED], strict: true)) {
139	            throw IllegalStateTransition::between($event->state, EventState::PUBLISHED);
140	        }
141	
142	        if ($event->state === EventState::DRAFT && ! $this->hasPublishableLanding($event)) {
143	            throw PublishPrerequisiteMissing::landingPage($event);
144	        }
145	    }
