147	    /**
148	     * @return array{allowed: bool, reason: string|null, attemptable: bool, reason_code?: string, audit?: array{status: string, message: string}}
149	     */
150	    public function publishReadiness(Event $event, ?User $actor): array
151	    {
152	        if (! $actor instanceof User) {
153	            return [
154	                'allowed' => false,
155	                'reason' => __('events.publish.unavailable.unauthorized'),
156	                'attemptable' => false,
157	            ];
158	        }
159	
160	        if (! $this->authz->canPublish($event, $actor)) {
161	            return [
162	                'allowed' => false,
163	                'reason' => __('events.publish.unavailable.unauthorized'),
164	                'attemptable' => false,
165	            ];
166	        }
167	
168	        if ($this->killSwitches->active(PlatformKillSwitchKey::PUBLISH)) {
169	            return [
170	                'allowed' => false,
171	                'reason' => __('events.publish.unavailable.platform_disabled'),
172	                'attemptable' => true,
173	            ];
174	        }
175	
176	        if ($this->operationalLocks->active($event, EventOperationalLockKey::PUBLISH)) {
177	            return [
178	                'allowed' => false,
179	                'reason' => __('events.publish.unavailable.operations_locked'),
180	                'attemptable' => false,
181	            ];
182	        }
183	
184	        if (! $this->entitlements->hasEntitlementForTeam($actor, $event->team_id, 'PUBLISH')) {
185	            return [
186	                'allowed' => false,
187	                'reason' => __('events.publish.unavailable.plan_gate'),
188	                'reason_code' => self::PUBLISH_REASON_PLAN_GATE,
189	                'attemptable' => false,
190	            ];
191	        }
192	
193	        if ($event->cancelled_at !== null) {
194	            return [
195	                'allowed' => false,
196	                'reason' => __('events.publish.unavailable.state_locked'),
197	                'attemptable' => false,
198	            ];
199	        }
200	
201	        if (! in_array($event->state, [EventState::DRAFT, EventState::PUBLISHED], strict: true)) {
202	            return [
203	                'allowed' => false,
204	                'reason' => __('events.publish.unavailable.not_draft'),
205	                'attemptable' => false,
206	            ];
207	        }
208	
209	        if ($event->state === EventState::DRAFT && ! $this->hasPublishableLanding($event)) {
210	            return [
211	                'allowed' => false,
212	                'reason' => __('events.publish.unavailable.landing_required'),
213	                'attemptable' => false,
214	            ];
215	        }
216	
217	        if ($event->state === EventState::PUBLISHED) {
218	            return [
219	                'allowed' => true,
220	                'reason' => null,
221	                'attemptable' => false,
222	            ];
223	        }
224	
225	        $auditDecision = $this->aiAuditRequests->currentPublishDecisionForEvent($event);
226	        $audit = [
227	            'status' => $auditDecision->status->value,
228	            'message' => $this->auditStatusMessage($auditDecision->status),
229	        ];
230	
231	        if (! $auditDecision->isApproved()) {
232	            return [
233	                'allowed' => false,
234	                'reason' => $audit['message'],
235	                'attemptable' => $auditDecision->status === AiAuditOrganizerStatus::PRE_REVIEW,
236	                'audit' => $audit,
237	            ];
238	        }
239	
240	        return [
241	            'allowed' => true,
242	            'reason' => null,
243	            'attemptable' => true,
244	            'audit' => $audit,
245	        ];
246	    }
