262	    /**
263	     * Story 2-5 — Cancel event (flag, NOT a state).
264	     *
265	     * Cancellation sets `cancelled_at`, `cancelled_by`, `cancel_reason` and is
266	     * allowed in any state EXCEPT LIVE / ENDED / SUSPENDED (per spec — those
267	     * states have their own paths: LIVE force-end via Super Admin, ENDED is
268	     * already terminal, SUSPENDED is read-only).
269	     *
270	     * Idempotent: re-calling on an already-cancelled event returns unchanged.
271	     *
272	     * Notification/automation side effects and the 30-day registration sweep
273	     * are handled outside this transaction via domain events and scheduled
274	     * cleanup.
275	     */
276	    public function cancel(Event $event, User $actor, string $reason): Event
277	    {
278	        // R1 BLOCKER #2 (2-5) — service-layer Gate.
279	        $this->authz->authorizeCancel($event, $actor);
280	
281	        // R2 (2-5) — separate-tx denied audit pattern, mirroring transition()'s
282	        // R2 fix at lines 459-487. Outer tx returns 'denied' WITHOUT touching
283	        // audit; the post-tx block emits the denied audit in its own tx wrapped
284	        // in try/catch + report() + always-throw, so a logger failure cannot
285	        // mask EventStateLocked or roll back unrelated writes. Success-path
286	        // audit STAYS inside the outer tx (AC1 atomic state+audit invariant).
287	        $result = DB::transaction(function () use ($event, $actor, $reason): array {
288	            $fresh = $this->events->lockEventForServiceWrite($event->getKey());
289	
290	            if ($fresh->cancelled_at !== null) {
291	                return [$fresh, 'noop'];
292	            }
293	
294	            if (in_array($fresh->state, [EventState::LIVE, EventState::ENDED, EventState::SUSPENDED], strict: true)) {
295	                // Bubble the decision out — denied audit is emitted post-tx in
296	                // its own transaction so a logger throw cannot mask the typed
297	                // EventStateLocked exception (2-3a R2 lesson).
298	                return [$fresh, 'denied'];
299	            }
300	
301	            $fresh->forceFill([
302	                'cancelled_at' => now(),
303	                'cancelled_by' => $actor->getKey(),
304	                'cancel_reason' => $reason,
305	            ])->save();
306	
307	            $this->auditLogger->log(
308	                event: EventAuditEvents::EVENT_CANCELLED,
309	                description: "Event {$fresh->getKey()} cancelled by {$actor->getKey()}",
310	                subject: $actor,
311	                target: $fresh,
312	                properties: [
313	                    'team_id' => $fresh->team_id,
314	                    'event_uuid' => $fresh->uuid,
315	                    'state_at_cancellation' => $fresh->state->value,
316	                    'reason' => $reason,
317	                ],
318	            );
319	
320	            return [$fresh, 'changed'];
321	        });
322	
323	        [$fresh, $outcome] = $result;
324	
325	        if ($outcome === 'denied') {
326	            // Best-effort denied-audit in a SEPARATE tx; logger failures are
327	            // reported but never mask EventStateLocked.
328	            try {
329	                DB::transaction(function () use ($fresh, $actor, $reason): void {
330	                    $this->auditLogger->log(
331	                        event: EventAuditEvents::EVENT_CANCEL_DENIED,
332	                        description: "Event {$fresh->getKey()} cancellation denied (state {$fresh->state->value})",
333	                        subject: $actor,
334	                        target: $fresh,
335	                        properties: [
336	                            'team_id' => $fresh->team_id,
337	                            'event_uuid' => $fresh->uuid,
338	                            'state' => $fresh->state->value,
339	                            'reason' => $reason,
340	                        ],
341	                    );
342	                });
343	            } catch (\Throwable $auditFailure) {
344	                if (function_exists('report')) {
345	                    report($auditFailure);
346	                } else {
347	                    error_log('[EventLifecycleService] cancel denied-audit storage failure: '.$auditFailure->getMessage());
348	                }
349	            }
350	
351	            throw EventStateLocked::for($fresh);
352	        }
353	
354	        // R1 HIGH #4 (2-5) — dispatch domain event post-commit on changed branch only.
355	        // DB::afterCommit() queues until the OUTERMOST tx commits so callers wrapping
356	        // cancel() in their own DB::transaction() that later rolls back do NOT see
357	        // the dispatch fire. Pinned by EventDomainEventDispatchOrderTest.
358	        if ($outcome === 'changed') {
359	            $cancelled = $fresh->refresh();
360	            DB::afterCommit(static fn () => EventDispatcher::dispatch(
361	                new EventCancelled($cancelled, $actor, $reason),
362	            ));
363	        }
364	
365	        return $fresh->refresh();
366	    }
367	}
