23	     * Setup the test environment
24	     */
25	    protected function setUp(): void
26	    {
27	        parent::setUp();
28	
29	        // RefreshDatabase wipes the permissions table every test, so we reseed
30	        // when it's empty. The old `$permissionsSeeded` static was dead code
31	        // (set but never read) and misleadingly suggested per-class caching
32	        // that couldn't work under RefreshDatabase. Removed 2026-04-23 per
33	        // test-review-1-3 isolation finding.
34	        $this->seedPermissionsOnce();
35	    }
36	    
37	    /**
38	     * Seed permissions only once per test run to avoid redundant seeding
39	     */
40	    protected function seedPermissionsOnce(): void
41	    {
42	        // Check if permissions table is empty (RefreshDatabase clears it)
43	        if (\App\Models\RolePermission::count() === 0) {
44	            $this->seed(\Database\Seeders\Testing\TestPermissionSeeder::class);
45	        }
