<?php

namespace Platform\Authz;

use Illuminate\Contracts\Cache\Repository as CacheRepository;
use Illuminate\Support\ServiceProvider;
use Platform\Authz\Core\CachingCapabilityChecker;
use Platform\Authz\Core\Contracts\CapabilityCheckerInterface;
use Platform\Authz\Core\Contracts\CapabilityRegistrarInterface;
use Platform\Authz\Core\Contracts\EffectiveScopeResolverInterface;
use Platform\Authz\Core\EffectiveScopeResolver;
use Platform\Authz\Core\GateCapabilityRegistrar;
use Platform\Authz\Http\RouteRequirementResolver;

class AuthzServiceProvider extends ServiceProvider
{
    /**
     * Register services.
     *
     * @return void
     */
    public function register(): void
    {
        // Merge package config
        $this->mergeConfigFrom(
            __DIR__ . '/../config/platform-authz.php',
            'platform-authz'
        );

        // Register GateCapabilityRegistrar
        $this->app->singleton(CapabilityRegistrarInterface::class, GateCapabilityRegistrar::class);

        // Register RouteRequirementResolver with special permissions from config
        $this->app->singleton(RouteRequirementResolver::class, function ($app) {
            return new RouteRequirementResolver(
                specialPermissions: (array) config('platform-authz.special_permissions', []),
            );
        });

        // Permission evaluation chain
        $this->app->singleton(\Platform\Authz\Core\RequestCacheService::class);
        $this->app->singleton(\Platform\Authz\Core\PermissionCacheService::class);
        $this->app->singleton(\Platform\Authz\Core\Contracts\PermissionRepositoryInterface::class, \Platform\Authz\Core\PermissionRepository::class);
        $this->app->singleton(\Platform\Authz\Core\PermissionOrchestrator::class);
        $this->app->singleton(\Platform\Authz\Core\PermissionEvaluator::class);
        $this->app->singleton(\Platform\Authz\Core\PermissionCapabilityChecker::class);

        // Default CapabilityCheckerInterface → PermissionCapabilityChecker
        // Host app can override this binding before the provider registers
        $this->app->bindIf(CapabilityCheckerInterface::class, \Platform\Authz\Core\PermissionCapabilityChecker::class);

        // Effective scope resolution (used by ResourcePolicy for model-instance authorization)
        $this->app->singleton(EffectiveScopeResolverInterface::class, EffectiveScopeResolver::class);
    }

    /**
     * Bootstrap services.
     *
     * @return void
     */
    public function boot(): void
    {
        // Publish config
        $this->publishes([
            __DIR__ . '/../config/platform-authz.php' => config_path('platform-authz.php'),
        ], 'platform-authz-config');

        // Always wrap the bound capability checker so request-level caching stays active.
        // Persistent caching remains configurable, but package authz is always on.
        $this->app->extend(CapabilityCheckerInterface::class, function ($inner, $app) {
            return new CachingCapabilityChecker(
                inner: $inner,
                cache: $app->make(CacheRepository::class),
                tenantContext: $app->make(\Platform\Tenancy\Contracts\TenantContextInterface::class),
                persistentCacheEnabled: (bool) config('platform-authz.persistent_cache_enabled', false),
                cacheTtl: (int) config('platform-authz.cache_ttl', 300),
            );
        });

        $registrar = $this->app->make(CapabilityRegistrarInterface::class);
        $registrar->register();
    }
}

