<?php

declare(strict_types=1);

namespace Platform\Authz\Core;

use Platform\Authz\Core\Enums\PermissionAction;
use Platform\Authz\Core\Enums\PermissionScope;

/**
 * Centralized registry for permission string generation and parsing.
 *
 * Resources are config-driven via config('platform-authz.resources')
 * so each host app defines its own domain resources (tickets, meetings, etc.).
 *
 * The ACTION_TO_SCOPES mapping and permission parsing logic is universal
 * across all apps sharing this permission model.
 */
class PermissionRegistry
{
    /** Fixed action→scope mapping (simple, explicit) */
    private const ACTION_TO_SCOPES = [
        'viewany' => ['own', 'team', 'global'],
        'view' => ['own', 'team', 'global'],
        'create' => ['team', 'global'],
        'update' => ['own', 'team', 'global'],
        'delete' => ['own', 'team', 'global'],
        'viewany_system_admins' => ['global'],
        'view_system_admins' => ['global'],
        'update_system_admins' => ['global'],
    ];

    /**
     * Get all configured resource names.
     *
     * @return array<string>
     */
    public static function resources(): array
    {
        return (array) config('platform-authz.resources', []);
    }

    /**
     * Get the action-to-scopes mapping.
     *
     * @return array<string, array<string>>
     */
    public static function actionToScopes(): array
    {
        return self::ACTION_TO_SCOPES;
    }

    /**
     * Generate all permissions for a given resource.
     *
     * @return array<string>
     */
    public static function forResource(string $resource): array
    {
        $permissions = [];
        foreach (self::ACTION_TO_SCOPES as $action => $scopes) {
            foreach ($scopes as $scope) {
                $permissions[] = "{$resource}.{$action}.{$scope}";
            }
        }
        return $permissions;
    }

